<?php declare(strict_types=1); namespace App\Modules\Tourism\Services; use App\Modules\Tourism\Models\TourismEvent; use RuntimeException; final class TourismEventService{private TourismEvent $m;public function __construct(){$this->m=new TourismEvent();}public function all($t,$d=false){return $this->m->all($t,$d);}public function find($t,$id,$d=false){return $this->m->find($t,$id,$d);}public function save($t,$id,$i,$u){$d=$this->v($i);$d['slug']=$this->slug($t,$this->slugify($d['title']),$id);return $this->m->save($t,$id,$d,$u);}public function delete($t,$id,$u){$this->m->delete($t,$id,$u);}public function restore($t,$id,$u){$this->m->restore($t,$id,$u);}public function providers($t){return app()->get('db')->fetchAll("SELECT id,legal_name,provider_type FROM tourism_providers WHERE tenant_id=? AND deleted_at IS NULL ORDER BY legal_name",[$t]);}private function v($i){$d=['provider_id'=>($i['provider_id']??'')===''?null:(int)$i['provider_id'],'title'=>trim((string)($i['title']??'')),'description'=>trim((string)($i['description']??''))?:null,'event_type'=>trim((string)($i['event_type']??''))?:null,'start_at'=>trim((string)($i['start_at']??'')),'end_at'=>trim((string)($i['end_at']??''))?:null,'venue'=>trim((string)($i['venue']??''))?:null,'city'=>trim((string)($i['city']??''))?:null,'district'=>trim((string)($i['district']??''))?:null,'state'=>trim((string)($i['state']??''))?:'Manipur','latitude'=>trim((string)($i['latitude']??''))?:null,'longitude'=>trim((string)($i['longitude']??''))?:null,'organizer_name'=>trim((string)($i['organizer_name']??''))?:null,'contact_phone'=>trim((string)($i['contact_phone']??''))?:null,'ticket_info'=>trim((string)($i['ticket_info']??''))?:null,'cover_image_path'=>trim((string)($i['cover_image_path']??''))?:null,'status'=>trim((string)($i['status']??'Draft'))?:'Draft','featured'=>empty($i['featured'])?0:1];if(!$d['title']||!$d['start_at'])throw new RuntimeException('Event title and start date/time are required.');return $d;}private function 